public str getName()
{
    return fieldPName(EcoResProductServiceWarranty, DistinctProduct);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::Int64);

    EcoResProductServiceWarranty warrantyProduct;

    while select DistinctProduct from warrantyProduct
    {
        if (!ret.in(warrantyProduct.DistinctProduct))
        {
            ret.add(warrantyProduct.DistinctProduct);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(EcoResProductServiceWarranty, DistinctProduct));
    qbr.value(queryValue(_value));
}
